    def minOperations(self, queries: List[List[int]]) -> int:
        def min_ops_for_query(l, r):
            # Create a max heap to efficiently get the two largest numbers
            heap = [-num for num in range(l, r + 1)]
            import heapq
            heapq.heapify(heap)

            operations = 0
            while len(heap) > 1:
                # Get the two largest numbers
                a = -heapq.heappop(heap)
                b = -heapq.heappop(heap)

                # Apply operation
                a_new = a // 4
                b_new = b // 4

                # Push back non-zero results
                if a_new > 0:
                    heapq.heappush(heap, -a_new)
                if b_new > 0:
                    heapq.heappush(heap, -b_new)

                operations += 1

            # Handle any remaining element
            if heap and -heap[0] > 0:
                operations += 1

            return operations

        total_operations = 0
        for l, r in queries:
            # Check if range is too large to materialize
            if r - l > 10**5:
                # Use a more memory-efficient approach for large ranges
                from collections import Counter

                # Count numbers by their values (floor division by 4)
                counter = Counter(range(l, r + 1))
                operations = 0

                while sum(counter.values()) > 0:
                    # Get the two largest numbers
                    nums = sorted(counter.keys(), reverse=True)

                    if len(nums) >= 2:
                        a, b = nums[0], nums[1]
                        counter[a] -= 1
                        counter[b] -= 1

                        if counter[a] == 0:
                            del counter[a]
                        if counter[b] == 0:
                            del counter[b]

                        a_new, b_new = a // 4, b // 4
                        if a_new > 0:
                            counter[a_new] += 1
                        if b_new > 0:
                            counter[b_new] += 1
                    else:
                        a = nums[0]
                        counter[a] -= 1
                        if counter[a] == 0:
                            del counter[a]

                        a_new = a // 4
                        if a_new > 0:
                            counter[a_new] += 1

                    operations += 1

                total_operations += operations
            else:
                total_operations += min_ops_for_query(l, r)

