class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        queue = deque([(x, 0)])  # (current_value, operations)
        visited = set([x])
        upper_bound = 2 * max(x, y)

        while queue:
            current, ops = queue.popleft()

            if current == y:
                return ops

            # Generate all possible next values
            next_values = []

            # Operation 1: Divide by 11 if divisible
            if current % 11 == 0:
                next_values.append(current // 11)

            # Operation 2: Divide by 5 if divisible
