        max_incr = 0

        for num in nums:
            incr = M - num
            sum_initial += incr
            if incr > max_incr:
                max_incr = incr

        if cost2 >= 2 * cost1:
            # It's better to use single operations always
            return (sum_initial * cost1) % MOD
        else:
            # Consider using pairs where possible
            if sum_initial >= 2 * max_incr:
                x = sum_initial // 2
                rem = sum_initial % 2
                cost = x * cost2 + rem * cost1
            else:
                # Most increments come from pairing with others
                x = sum_initial - max_incr
                rem = max_incr - x
                cost = x * cost2 + rem * cost1

            return cost % MOD

