class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        max_val = max(nums)

        # Count how many numbers are divisible by each value
        divisible = [0] * (max_val + 1)
        for num in nums:
            for g in range(1, int(num**0.5) + 1):
                if num % g == 0:
                    divisible[g] += 1
                    if g != num // g:
                        divisible[num // g] += 1

        # Count pairs with GCD exactly g
        count = [0] * (max_val + 1)
        for g in range(max_val, 0, -1):
            if divisible[g] >= 2:
                count[g] = divisible[g] * (divisible[g] - 1) // 2
                for k in range(2 * g, max_val + 1, g):
                    count[g] -= count[k]

        # Build cumulative frequency
        gcd_values = []
        cumulative = []
        total = 0
        for g in range(1, max_val + 1):
            if count[g] > 0:
                gcd_values.append(g)
                total += count[g]
                cumulative.append(total)

        # Answer queries using binary search
        def binary_search(target):
            left, right = 0, len(cumulative) - 1
            while left <= right:
                mid = (left + right) // 2
                if cumulative[mid] > target:
                    right = mid - 1
                else:
                    left = mid + 1
            return left

        return [gcd_values[binary_search(q)] for q in queries]

