            # Remove the effect of operations that no longer cover position i
            if i >= k:
                current_ops -= operations[i - k]

            # Calculate remaining value after applying current operations
            remaining = nums[i] - current_ops

            if remaining < 0:
                return False

            if remaining > 0:
                # We need to start `remaining` operations at position i
                if i + k > n:  # Can't start an operation here
                    return False
                operations[i] = remaining
                current_ops += remaining

        return True

