from sortedcontainers import SortedDict

class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)

        # If all elements are non-positive, return the largest element
        if all(num <= 0 for num in nums):
            return max(nums)

        # SortedDict to map val to maximum dp
        sd = SortedDict()

        for i in range(n):
            v = nums[i] - i

            # Find the maximum dp for all v' <= v
            max_dp = 0
            idx = sd.bisect_right(v) - 1
            if idx >= 0:
                max_dp = sd.peekitem(idx)[1]

            # Update the SortedDict
            curr_dp = max_dp + nums[i]
            if curr_dp <= 0:  # Skip if it doesn't increase our dp
                continue

            if v in sd:
                sd[v] = max(sd[v], curr_dp)
            else:
                sd[v] = curr_dp

            # Ensure our invariant
            keys_to_remove = []
            idx = sd.bisect_right(v)
            while idx < len(sd):
                key, val = sd.peekitem(idx)
                if val <= curr_dp:
                    keys_to_remove.append(key)
                    idx += 1
                else:
                    break

            for key in keys_to_remove:
                del sd[key]

        # Return the maximum dp value
        return max(sd.values()) if sd else max(nums)

