import collections

class SegmentTree:
    def __init__(self, size: int):
        self.size = size
        self.tree = [float('inf')] * (4 * size) 
        self.actual_freqs = [0] * size # Stores frequency of each value

    def _update_tree(self, node_idx: int, range_l: int, range_r: int, val_to_update: int):
        if range_l == range_r: # Leaf node
            if self.actual_freqs[val_to_update] > 0:
                self.tree[node_idx] = val_to_update
            else:
                self.tree[node_idx] = float('inf')
            return

        mid = (range_l + range_r) // 2
        if val_to_update <= mid:
            self._update_tree(2 * node_idx, range_l, mid, val_to_update)
        else:
            self._update_tree(2 * node_idx + 1, mid + 1, range_r, val_to_update)

        self.tree[node_idx] = min(self.tree[2 * node_idx], self.tree[2 * node_idx + 1])

    def increment_freq(self, val: int):
        self.actual_freqs[val] += 1
        if self.actual_freqs[val] == 1: # Only update tree if frequency changes from 0 to 1
             self._update_tree(1, 0, self.size - 1, val)

    def get_freq(self, val: int) -> int:
        return self.actual_freqs[val]

    def get_min_val_with_positive_freq(self) -> float:
        return self.tree[1]

    def _query_range_min(self, node_idx: int, current_range_l: int, current_range_r: int, query_l: int, query_r: int) -> float:
        if current_range_l > query_r or current_range_r < query_l:
            return float('inf')
        if query_l <= current_range_l and current_range_r <= query_r:
            return self.tree[node_idx]

        mid = (current_range_l + current_range_r) // 2
        res_left = self._query_range_min(2 * node_idx, current_range_l, mid, query_l, query_r)
        res_right = self._query_range_min(2 * node_idx + 1, mid + 1, current_range_r, query_l, query_r)
        return min(res_left, res_right)

    def get_next_min_val_with_positive_freq(self, val: int) -> float:
        if val + 1 >= self.size:
            return float('inf')
        return self._query_range_min(1, 0, self.size - 1, val + 1, self.size - 1)


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: list[list[int]]) -> int:
        if n == 0: # Should not happen based on constraints but good for robustness
            return 0

        num_original_pairs = len(conflictingPairs)

        adj = collections.defaultdict(list)
        for idx, pair in enumerate(conflictingPairs):
            u, v = pair[0], pair[1]
            L_p, R_p = min(u, v), max(u, v) # L_p, R_p are 1-indexed
            # R_p_val is R_p-1, which is 0-indexed if thinking of array indices
            # but here it's max element value - 1
            adj[L_p].append((R_p - 1, idx))

        delta_S = [0.0] * num_original_pairs 
        s_orig = 0.0

        active_R_val_to_pids_list = collections.defaultdict(list)

        st = SegmentTree(n) # Operates on values 0 to n-1

        for i in range(n, 0, -1): # i is 1-indexed start of subarray
            if i in adj:
                for R_val, p_id in adj[i]:
                    st.increment_freq(R_val)
                    active_R_val_to_pids_list[R_val].append(p_id)

            m1_val = st.get_min_val_with_positive_freq() # This is an R_p-1 type value

            # current_j_boundary is the max allowed 1-indexed end element for a subarray starting at i
            current_j_boundary = n 
            if m1_val != float('inf'):
                current_j_boundary = min(n, int(m1_val)) 

            s_orig += max(0, current_j_boundary - i + 1)

            if m1_val != float('inf'):
                m1_int = int(m1_val)
                if st.get_freq(m1_int) == 1:
                    # Exactly one active pair pk has R_{pk}-1 = m1_int.
                    # This means active_R_val_to_pids_list[m1_int] must contain exactly one p_id.
                    pk_id = active_R_val_to_pids_list[m1_int][0]

                    m2_val = st.get_next_min_val_with_positive_freq(m1_int)

                    # If pk_id is removed, new j_boundary for this i is min(n, m2_val)
                    new_j_boundary_if_pk_removed = n
                    if m2_val != float('inf'):
                         new_j_boundary_if_pk_removed = min(n, int(m2_val))

                    # The change in contribution for this specific i:
                    # (new_j_boundary - i + 1) - (current_j_boundary - i + 1)
                    # = new_j_boundary - current_j_boundary
                    delta_S[pk_id] += (new_j_boundary_if_pk_removed - current_j_boundary)

        # If there are no conflicting pairs initially, the problem implies we remove a "dummy" one.
        # The sum S_orig would be n*(n+1)/2. max_total_S would be this.
        # Constraints: 1 <= conflictingPairs.length. So num_original_pairs >= 1.
        max_total_S = 0.0
        if num_original_pairs == 0: # Should not be reached due to constraints
             return n * (n + 1) // 2

        for k_idx in range(num_original_pairs):
            max_total_S = max(max_total_S, s_orig + delta_S[k_idx])

        return int(round(max_total_S)) # round handles potential float inaccuracies if any

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        count = 0
        and_counts = {}

        for num in nums:
            new_and_counts = {}

            # Single element subarray
            new_and_counts[num] = new_and_counts.get(num, 0) + 1

            # Extend previous subarrays
            for and_val, cnt in and_counts.items():
                new_val = and_val & num
                new_and_counts[new_val] = new_and_counts.get(new_val, 0) + cnt

            # Count subarrays with AND = k
            if k in new_and_counts:
                count += new_and_counts[k]

            and_counts = new_and_counts

        return count

